function refId(v) { return Array.isArray(v) ? v[1] : v; }
const cfg = $('Set Config').first().json;
const users = $('Get Users').all().map((i) => i.json).filter((r) => r.id != null);
const user = users.find((u) => u.id === cfg.userId);
if (!user) return [{ json: { ...cfg, ok: false, error: 'unknown_user' } }];

const configRow = $('Get Config').all().map((i) => i.json).find((r) => r.id != null);
const MAX_ENERGY = (configRow && configRow.DigMaxEnergy) || 5;
const REGEN_SECONDS = (configRow && configRow.DigRegenSeconds) || 60;
const BOARD_SIZE = 16;
// Empreintes de tresors : la plupart tiennent sur 1 tuile, mais certaines
// (surtout la carte, la plus rare) sont etalees sur plusieurs tuiles - il
// faut alors creuser TOUTES ses tuiles pour liberer l'objet.
const TREASURE_SHAPES = [
  { cells: 4, reward: 'card' },
  { cells: 2, reward: 'booster' },
  { cells: 2, reward: 'bigDust' },
  { cells: 1, reward: 'smallDust' },
  { cells: 1, reward: 'smallDust' },
  { cells: 1, reward: 'smallDust' }
];

function generateBoard() {
  const order = Array.from({ length: BOARD_SIZE }, (_, i) => i);
  for (let i = order.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const tmp = order[i]; order[i] = order[j]; order[j] = tmp;
  }
  const tiles = Array.from({ length: BOARD_SIZE }, () => ({ t: null, d: false }));
  const treasures = [];
  let cursor = 0;
  TREASURE_SHAPES.forEach((shape) => {
    const treasureIndex = treasures.length;
    treasures.push({ cells: shape.cells, dug: 0, reward: shape.reward, done: false });
    for (let i = 0; i < shape.cells; i++) {
      tiles[order[cursor]].t = treasureIndex;
      cursor++;
    }
  });
  return { tiles, treasures };
}

const now = Math.floor(Date.now() / 1000);
const storedEnergy = user.DigEnergy != null ? user.DigEnergy : MAX_ENERGY;
const lastAt = user.LastDigEnergyAt || now;
let currentEnergy = storedEnergy;
let secondsUntilNext = null;
if (storedEnergy < MAX_ENERGY) {
  const elapsed = Math.max(0, now - lastAt);
  const gained = Math.floor(elapsed / REGEN_SECONDS);
  currentEnergy = Math.min(MAX_ENERGY, storedEnergy + gained);
  if (currentEnergy < MAX_ENERGY) secondsUntilNext = REGEN_SECONDS - (elapsed % REGEN_SECONDS);
}

let board = null;
try { board = user.DigBoardState ? JSON.parse(user.DigBoardState) : null; } catch (e) { board = null; }
let boardDirty = false;
if (!board || !Array.isArray(board.tiles) || board.tiles.length !== BOARD_SIZE || !Array.isArray(board.treasures)) {
  board = generateBoard();
  boardDirty = true;
}

if (cfg.action === 'dig') {
  if (currentEnergy < 1) return [{ json: { ...cfg, ok: false, error: 'no_energy' } }];
  const tileIndex = Number(cfg.tileIndex);
  if (!Number.isInteger(tileIndex) || tileIndex < 0 || tileIndex >= BOARD_SIZE) {
    return [{ json: { ...cfg, ok: false, error: 'invalid_tile' } }];
  }
  const tile = board.tiles[tileIndex];
  if (tile.d) return [{ json: { ...cfg, ok: false, error: 'tile_already_dug' } }];

  const newEnergy = currentEnergy - 1;
  tile.d = true;

  let outcome = 'nothing', dustGained = 0, boosterGranted = false, revealed = false, remaining = 0;
  let cardId = null, serialNumber = null, maxSerial = null, cardName = null;

  if (tile.t != null) {
    const treasure = board.treasures[tile.t];
    treasure.dug++;
    if (treasure.dug >= treasure.cells) {
      treasure.done = true;
      revealed = true;
      if (treasure.reward === 'smallDust') { outcome = 'dust'; dustGained = 5 + Math.floor(Math.random() * 11); }
      else if (treasure.reward === 'bigDust') { outcome = 'dust'; dustGained = 25 + Math.floor(Math.random() * 26); }
      else if (treasure.reward === 'booster') { outcome = 'booster'; boosterGranted = true; }
      else if (treasure.reward === 'card') {
        const pulls = $('Get Pulls').all().map((i) => i.json).filter((r) => r.id != null);
        const cards = $('Get Cards').all().map((i) => i.json).filter((r) => r.id != null);
        const rarities = $('Get Rarities').all().map((i) => i.json).filter((r) => r.id != null);
        const countByCard = {};
        pulls.forEach((p) => { const cid = refId(p.Card); countByCard[cid] = (countByCard[cid] || 0) + 1; });
        const commonRarity = rarities.filter((r) => r.SortOrder != null).sort((a, b) => (a.SortOrder || 0) - (b.SortOrder || 0))[0];
        const candidates = cards.filter((c) => c.Active !== false && !c.IsPromo && commonRarity && refId(c.Rarity) === commonRarity.id && (countByCard[c.id] || 0) < (c.MaxSerial || 100));
        if (candidates.length) {
          const picked = candidates[Math.floor(Math.random() * candidates.length)];
          cardId = picked.id;
          cardName = picked.Name;
          maxSerial = picked.MaxSerial || 100;
          serialNumber = (countByCard[picked.id] || 0) + 1;
          outcome = 'card';
        } else {
          // Aucune carte commune disponible (toutes epuisees) : on degrade
          // silencieusement vers de la poussiere plutot que de faire echouer
          // la fouille (le joueur a quand meme depense son energie et libere
          // les 4 tuiles).
          outcome = 'dust';
          dustGained = 30;
        }
      }
    } else {
      outcome = 'partial';
      remaining = treasure.cells - treasure.dug;
    }
  }

  // Plateau entierement fouille : on prepare tout de suite un nouveau
  // plateau pour la prochaine visite plutot que de laisser un ecran vide.
  const boardCleared = board.tiles.every((t) => t.d);
  const finalBoard = boardCleared ? generateBoard() : board;

  return [{ json: {
    ...cfg, ok: true, mutation: 'dig', boardDirty: true,
    newEnergy, outcome, dustGained, boosterGranted, revealed, remaining, tileIndex, boardCleared,
    board: JSON.stringify(finalBoard),
    revealBoard: JSON.stringify(board),
    newStardust: (user.StardustCount || 0) + dustGained,
    newBoosterCount: (user.BoosterCount || 0) + (boosterGranted ? 1 : 0),
    cardId, cardName, serialNumber, maxSerial
  } }];
}

// action === 'status' (ou toute autre valeur) : lecture seule pour l'energie,
// mais persiste un plateau tout juste genere (premiere visite du joueur, ou
// etat corrompu) pour qu'il reste stable au prochain appel.
return [{ json: {
  ...cfg, ok: true, mutation: 'none', boardDirty,
  energy: currentEnergy, maxEnergy: MAX_ENERGY, secondsUntilNext, regenSeconds: REGEN_SECONDS,
  board: JSON.stringify(board),
  revealBoard: JSON.stringify(board)
} }];

const d = $('Dispatch Action').first().json;
const board = JSON.parse(d.revealBoard);
const tiles = board.tiles.map((t) => {
  if (!t.d) return { dug: false };
  if (t.t == null) return { dug: true, treasure: null };
  const tr = board.treasures[t.t];
  return { dug: true, treasure: tr.done ? { reward: tr.reward, done: true } : { done: false, remaining: tr.cells - tr.dug } };
});
return [{ json: {
  dug: true,
  tileIndex: d.tileIndex,
  outcome: d.outcome,
  revealed: d.revealed,
  remaining: d.remaining,
  dustGained: d.dustGained || 0,
  boosterGranted: d.boosterGranted || false,
  card: d.outcome === 'card' ? { cardId: d.cardId, name: d.cardName, serialNumber: d.serialNumber, maxSerial: d.maxSerial } : null,
  newEnergy: d.newEnergy,
  boardCleared: d.boardCleared,
  tiles
} }];

const d = $('Dispatch Action').first().json;
const board = JSON.parse(d.revealBoard);
const tiles = board.tiles.map((t) => {
  if (!t.d) return { dug: false };
  if (t.t == null) return { dug: true, treasure: null };
  const tr = board.treasures[t.t];
  return { dug: true, treasure: tr.done ? { reward: tr.reward, done: true } : { done: false, remaining: tr.cells - tr.dug } };
});
return [{ json: { energy: d.energy, maxEnergy: d.maxEnergy, secondsUntilNext: d.secondsUntilNext, regenSeconds: d.regenSeconds, tiles } }];
